                result.add(i);
            }
        }
    }

    while (!queue.isEmpty()) {
        long cur = queue.poll();
        int lastDigit = (int) (cur % 10);

        // Next digit could be lastDigit - 1
        int nextDigit = lastDigit - 1;
        if (nextDigit >= 0) {
            long next = cur * 10 + nextDigit;
            if (next <= high) {
